import type { StageStep } from './stageViews';
import type { ChainName } from './handModel';

export interface AuthoredPoint { nut: [number, number, number]; saddle: [number, number, number] }
export interface AuthoredPose { name: string; frets: (number | null)[] }
export interface AuthoredSceneInfo {
  layout: { frets: number[]; strings: AuthoredPoint[] };
  poses: AuthoredPose[];
  strumContacts: { Acal: number[]; Ycal: number[] };
}
export interface AuthoredCurve { times: ArrayLike<number>; values: ArrayLike<number>; size: 3 | 4 }
export interface AuthoredTimeKey { at: number; time: number }
export interface AuthoredPluck { string: number; offset: number; finger: ChainName; clip: string }

/** A pinch needs distinct fingers, even when a sparse voicing puts two of its notes on bass strings. */
export function authoredPlucks(notes: StageStep['notes']): AuthoredPluck[] {
  const groups = new Map<number, typeof notes[number][]>();
  for (const note of notes) {
    if (!Number.isInteger(note.stringIndex) || note.stringIndex < 0 || note.stringIndex > 5 || !Number.isFinite(note.offset) || note.offset < 0) {
      throw new Error('Invalid original fingerpicking note');
    }
    const group = groups.get(note.offset) ?? [];
    if (group.some(item => item.stringIndex === note.stringIndex)) throw new Error('A string cannot be plucked twice at the same time');
    group.push(note); groups.set(note.offset, group);
  }
  const result: AuthoredPluck[] = [];
  for (const [offset, group] of groups) {
    group.sort((a, b) => b.stringIndex - a.stringIndex);
    if (group.length > 4) throw new Error('A fingerpicked pinch supports at most four simultaneous strings');
    if (group[0].stringIndex >= 3) {
      const string = group.shift()!.stringIndex;
      result.push({ string, offset, finger: 'thumb', clip: authoredPickingFinger(string) });
    }
    let next = 0;
    group.forEach((note, i) => {
      const finger = Math.min(3 - (group.length - i), Math.max(next, 2 - note.stringIndex));
      next = finger + 1;
      result.push({ string: note.stringIndex, offset, finger: (['index', 'middle', 'ring'] as const)[finger], clip: ['i', 'm', 'a'][finger] });
    });
  }
  return result;
}

const record = (value: unknown): Record<string, unknown> => {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('Invalid original-scene metadata');
  return value as Record<string, unknown>;
};
const number = (value: unknown): number => {
  if (typeof value !== 'number' || !Number.isFinite(value)) throw new Error('Original-scene coordinates must be finite');
  return value;
};
const array = (value: unknown, length?: number): unknown[] => {
  if (!Array.isArray(value) || (length !== undefined && value.length !== length)) throw new Error('Incomplete original-scene metadata');
  return value;
};
const point = (value: unknown): [number, number, number] => {
  const components = array(value, 3).map(number);
  return [components[0], components[1], components[2]];
};

export function readAuthoredSceneInfo(value: unknown): AuthoredSceneInfo {
  const source = record(value), layout = record(source.layout), contacts = record(source.strumContacts);
  if (source.version !== 1) throw new Error('Unsupported original-scene version');
  const frets = array(layout.frets, 21).map(number);
  if (frets.some((fret, i) => i > 0 && fret <= frets[i - 1])) throw new Error('Original fret positions are out of order');
  const strings = array(layout.strings, 6).map(value => {
    const string = record(value);
    const nut = point(string.nut), saddle = point(string.saddle);
    if (saddle[0] <= nut[0]) throw new Error('Invalid original string length');
    return { nut, saddle };
  });
  const poses = array(source.poses, 96).map(value => {
    const pose = record(value);
    if (typeof pose.name !== 'string' || !/^[A-G]#?(?:m|7|m7|maj7|sus2|sus4|7sus4)?$/.test(pose.name)) {
      throw new Error('Invalid original chord name');
    }
    const frets = array(pose.frets, 6).map(value => {
      if (value === null) return null;
      const fret = number(value);
      if (!Number.isInteger(fret) || fret < 0 || fret > 20) throw new Error('Invalid original chord shape');
      return fret;
    });
    return { name: pose.name, frets };
  });
  if (new Set(poses.map(pose => pose.name)).size !== poses.length) throw new Error('Duplicate original chord poses');
  const crossings = (name: 'Acal' | 'Ycal') => {
    const times = array(contacts[name], 6).map(value => number(record(value).time));
    if (times.some((time, i) => time <= 0 || time >= .21 || (i > 0 && (name === 'Acal' ? time >= times[i - 1] : time <= times[i - 1])))) {
      throw new Error('Original strum crossings are out of order');
    }
    return times;
  };
  return { layout: { frets, strings }, poses, strumContacts: { Acal: crossings('Acal'), Ycal: crossings('Ycal') } };
}

/** Open and muted strings need the same unfretted hand pose; positive frets must match exactly. */
export function findAuthoredPose(poses: readonly AuthoredPose[], frets: readonly (number | null)[]): AuthoredPose | null {
  if (frets.length !== 6 || frets.some(fret => fret !== null && (!Number.isInteger(fret) || fret < 0 || fret > 20))) {
    throw new Error('A hand pose needs six valid frets');
  }
  return poses.find(pose => pose.frets.every((fret, s) => (fret ?? 0) === (frets[s] ?? 0))) ?? null;
}

export function validateAuthoredCurve(curve: AuthoredCurve): void {
  const { times, values, size } = curve;
  if (!times.length || values.length !== times.length * size * 3) throw new Error('Incomplete original animation curve');
  for (let i = 0; i < times.length; i++) {
    if (!Number.isFinite(times[i]) || times[i] < 0 || (i > 0 && times[i] <= times[i - 1])) throw new Error('Invalid original animation times');
  }
  for (let i = 0; i < values.length; i++) if (!Number.isFinite(values[i])) throw new Error('Invalid original animation value');
}

/** Unity's unweighted Hermite tangents are retained as glTF CUBICSPLINE, including quaternion normalization. */
export function sampleAuthoredCurve(curve: AuthoredCurve, time: number, out: Float32Array): void {
  const { times, values, size } = curve;
  const last = times.length - 1;
  if (time <= times[0] || time >= times[last]) {
    const offset = ((time <= times[0] ? 0 : last) * 3 + 1) * size;
    for (let k = 0; k < size; k++) out[k] = values[offset + k];
  } else {
    let left = 0, right = last;
    while (right - left > 1) {
      const middle = (left + right) >> 1;
      if (times[middle] > time) right = middle; else left = middle;
    }
    const dt = times[right] - times[left], t = (time - times[left]) / dt, t2 = t * t, t3 = t2 * t;
    for (let k = 0; k < size; k++) {
      const a = left * size * 3 + k, b = right * size * 3 + k;
      out[k] = (2 * t3 - 3 * t2 + 1) * values[a + size] + (t3 - 2 * t2 + t) * dt * values[a + size * 2]
        + (-2 * t3 + 3 * t2) * values[b + size] + (t3 - t2) * dt * values[b];
    }
  }
  if (size === 4) {
    const length = Math.hypot(out[0], out[1], out[2], out[3]);
    if (length < 1e-8) throw new Error('Original animation contains an invalid rotation');
    for (let k = 0; k < 4; k++) out[k] /= length;
  }
}

/** Retimes the original spatial stroke so its measured string crossings coincide with scheduled notes. */
export function authoredStrokeKeys(
  contacts: readonly number[], duration: number, step: StageStep, at: number,
): AuthoredTimeKey[] {
  if (!Number.isFinite(at) || !Number.isFinite(duration) || duration <= 0 || !Number.isFinite(step.stepSeconds) || step.stepSeconds <= 0) {
    throw new Error('Original strumming needs a valid playback clock');
  }
  const notes = [...step.notes].sort((a, b) => a.offset - b.offset);
  if (!notes.length) return [{ at, time: 0 }, { at: at + step.stepSeconds * .6, time: duration }];
  const lead = Math.min(.06, step.stepSeconds * .2), tail = lead;
  const keys = notes.map(note => {
    const time = contacts[note.stringIndex];
    if (!Number.isFinite(time) || !Number.isFinite(note.offset) || note.offset < 0) throw new Error('Invalid original strum note');
    return { at: at + note.offset, time };
  });
  for (let i = 1; i < keys.length; i++) {
    if (keys[i].at <= keys[i - 1].at || keys[i].time <= keys[i - 1].time) throw new Error('Original strum notes must follow the stroke direction');
  }
  const crossings = [...contacts].sort((a, b) => a - b);
  const first = keys[0].time, last = keys[keys.length - 1].time;
  const firstIndex = crossings.indexOf(first), lastIndex = crossings.indexOf(last);
  return [
    { at: keys[0].at - lead, time: firstIndex > 0 ? first - .45 * (first - crossings[firstIndex - 1]) : 0 },
    ...keys,
    { at: keys[keys.length - 1].at + tail, time: lastIndex < crossings.length - 1 ? last + .45 * (crossings[lastIndex + 1] - last) : duration },
  ];
}

export function authoredTime(keys: readonly AuthoredTimeKey[], now: number): number {
  if (now <= keys[0].at) return keys[0].time;
  const last = keys[keys.length - 1];
  if (now >= last.at) return last.time;
  let i = 0;
  while (keys[i + 1].at < now) i++;
  const a = keys[i], b = keys[i + 1];
  return a.time + (b.time - a.time) * (now - a.at) / (b.at - a.at);
}

export function authoredPickingFinger(stringIndex: number): string {
  const name = ['a', 'm', 'i', '4_p', '5_p', '6_p'][stringIndex];
  if (!name) throw new Error('Original picking needs a string from 1 to 6');
  return name;
}
