import * as THREE from 'three';
import { GLTFLoader, type GLTF } from 'three/addons/loaders/GLTFLoader.js';
import {
  authoredPickingFinger, authoredPlucks, authoredStrokeKeys, authoredTime, findAuthoredPose, readAuthoredSceneInfo,
  sampleAuthoredCurve, validateAuthoredCurve,
  type AuthoredCurve, type AuthoredPose, type AuthoredSceneInfo, type AuthoredTimeKey,
} from './authoredMotion';
import { SKIN_TONES, type SkinTone } from './guitarLook';
import { AUTHORED_HAND_POSE_VERSION, AuthoredHandRig, authoredStringPoint, readAuthoredHandPoses, type AuthoredHandPoses } from './authoredHandRig';
import type { ChainName } from './handModel';
import type { StageClipChoice, StageFamily, StageStep } from './stageViews';

interface BoundTrack extends AuthoredCurve { node: THREE.Object3D; property: 'position' | 'quaternion' | 'scale' }
interface BoundClip { name: string; duration: number; tracks: BoundTrack[] }
interface BonePose { position: THREE.Vector3; quaternion: THREE.Quaternion }
interface ChordChange { key: string; pose: AuthoredPose; start: number; end: number }
interface Stroke { clip: string; keys: AuthoredTimeKey[] }
interface Pluck { at: number; string: number }
interface FingerPluck extends Pluck { finger: ChainName; clip: string }
type Frets = readonly (number | null)[];

const MOTIONS: Readonly<Record<string, string>> = {
  StrDef: 'Strumming rest', ArpDef: 'Fingerpicking rest',
  Acal: 'Downstroke', Ycal: 'Upstroke', AsaKu: 'Downstroke above strings', YuKu: 'Upstroke above strings',
  Amut: 'Muted downstroke (motion only)',
  i_in: 'Index pluck', i_out: 'Index return', m_in: 'Middle pluck', m_out: 'Middle return',
  a_in: 'Ring pluck', a_out: 'Ring return',
  '4_p_in': 'Thumb pluck - string 4', '4_p_out': 'Thumb return - string 4', '4_p_t_out': 'Thumb rest - string 4',
  '5_p_in': 'Thumb pluck - string 5', '5_p_out': 'Thumb return - string 5', '5_p_t_out': 'Thumb rest - string 5',
  '6_p_in': 'Thumb pluck - string 6', '6_p_out': 'Thumb return - string 6', '6_p_t_out': 'Thumb rest - string 6',
};
const smooth = (value: number) => { const t = THREE.MathUtils.clamp(value, 0, 1); return t * t * (3 - 2 * t); };
const shapeKey = (frets: Frets) => frets.map(fret => fret === null ? 'x' : fret).join('.');
const SAMPLE = new Float32Array(4);
const POSITION = new THREE.Vector3(), ROTATION = new THREE.Quaternion();
let sourceBuffer: Promise<{ buffer: ArrayBuffer; poses: AuthoredHandPoses }> | null = null;

/** Only immutable source data is shared; each scene owns its textures, skeletons, pose cache and GPU resources. */
export async function loadApkGuitar(): Promise<ApkGuitar3D> {
  if (!sourceBuffer) {
    const resource = async (name: string) => {
      const response = await fetch(`${import.meta.env.BASE_URL}models/apk/${name}`);
      if (!response.ok) throw new Error(`Original acoustic scene returned ${response.status}`);
      return response;
    };
    sourceBuffer = Promise.all([
      resource('acoustic-scene.glb').then(response => response.arrayBuffer()),
      resource(`hand-poses.json?v=${AUTHORED_HAND_POSE_VERSION}`).then(response => response.json()).then(readAuthoredHandPoses),
    ]).then(async ([buffer, poses]) => {
      const hash = [...new Uint8Array(await crypto.subtle.digest('SHA-256', buffer))].map(byte => byte.toString(16).padStart(2, '0')).join('');
      if (hash !== poses.sceneSha256) throw new Error('The acoustic scene and prepared hands do not match. Reload or retry.');
      return { buffer, poses };
    });
    sourceBuffer.catch(() => { sourceBuffer = null; });
  }
  const source = sourceBuffer;
  let gltf: GLTF | undefined;
  try {
    const { buffer, poses } = await source;
    gltf = await new GLTFLoader().parseAsync(buffer, '');
    return new ApkGuitar3D(gltf, poses);
  } catch (error) {
    if (sourceBuffer === source) sourceBuffer = null;
    if (gltf) disposeScene(gltf.scene);
    throw error;
  }
}

function disposeScene(root: THREE.Object3D): void {
  const geometries = new Set<THREE.BufferGeometry>(), materials = new Set<THREE.Material>();
  const textures = new Set<THREE.Texture>(), skeletons = new Set<THREE.Skeleton>(), bitmaps = new Set<ImageBitmap>();
  root.traverse(object => {
    if (object instanceof THREE.Mesh) {
      geometries.add(object.geometry);
      for (const material of Array.isArray(object.material) ? object.material : [object.material]) materials.add(material);
    }
    if (object instanceof THREE.SkinnedMesh) skeletons.add(object.skeleton);
  });
  for (const material of materials) {
    for (const value of Object.values(material)) if (value instanceof THREE.Texture) textures.add(value);
    material.dispose();
  }
  for (const texture of textures) {
    const image: unknown = texture.image;
    if (typeof ImageBitmap !== 'undefined' && image instanceof ImageBitmap) bitmaps.add(image);
    texture.dispose();
  }
  for (const geometry of geometries) geometry.dispose();
  for (const skeleton of skeletons) skeleton.dispose();
  for (const image of bitmaps) image.close();
  root.removeFromParent();
}

export class ApkGuitar3D {
  readonly root: THREE.Group;
  readonly info: AuthoredSceneInfo;
  readonly choices: readonly StageClipChoice[];
  private readonly clips = new Map<string, BoundClip>();
  private readonly left: THREE.Object3D;
  private readonly right: THREE.Object3D;
  private readonly pick: THREE.Object3D;
  private readonly leftBones: THREE.Object3D[];
  private readonly fretting: AuthoredHandRig;
  private readonly picking: AuthoredHandRig;
  private readonly pluckContacts = new Map<string, THREE.Vector3>();
  private readonly skin = new Set<THREE.MeshStandardMaterial>();
  private readonly strings: { materials: THREE.MeshStandardMaterial[]; lastHit: number }[];
  private chordQueue: ChordChange[] = [];
  private chordChange: { from: BonePose[]; to: BonePose[]; start: number; end: number } | null = null;
  private targetKey = '';
  private pose: AuthoredPose | null = null;
  private strokes: Stroke[] = [];
  private plucks: FingerPluck[] = [];
  private hits: Pluck[] = [];
  private family: StageFamily = 'strum';
  private thumb = 4;
  private demo: { clip: string; start: number; chord: boolean } | null = null;
  private handsVisible = true;
  private disposed = false;

  constructor(gltf: GLTF, prepared?: AuthoredHandPoses) {
    this.root = gltf.scene;
    this.info = readAuthoredSceneInfo(gltf.userData);
    const required = (name: string) => {
      const object = this.root.getObjectByName(name);
      if (!object) throw new Error(`Original scene is missing ${name}`);
      return object;
    };
    this.left = required('APK_Left');
    this.right = required('APK_Right');
    this.pick = required('APK_Pick');
    for (const clip of gltf.animations) {
      const tracks = clip.tracks.map(track => {
        const dot = track.name.lastIndexOf('.'), property = track.name.slice(dot + 1);
        if (property !== 'position' && property !== 'quaternion' && property !== 'scale') throw new Error('Unsupported original animation property');
        const curve: BoundTrack = {
          node: required(track.name.slice(0, dot)), property, size: property === 'quaternion' ? 4 : 3,
          times: track.times, values: track.values,
        };
        validateAuthoredCurve(curve);
        return curve;
      });
      this.clips.set(clip.name, { name: clip.name, duration: clip.duration, tracks });
    }
    for (const name of [...this.info.poses.map(pose => pose.name), ...Object.keys(MOTIONS)]) {
      if (!this.clips.has(name)) throw new Error(`Original animation ${name} is missing`);
    }
    if (this.clips.size !== 118) throw new Error('The original animation catalogue is incomplete');
    this.choices = [
      ...this.info.poses.map(pose => ({ name: pose.name, label: pose.name, kind: 'chord' as const })),
      ...Object.entries(MOTIONS).map(([name, label]) => ({ name, label, kind: 'motion' as const })),
    ];
    const left = new Set<THREE.Object3D>();
    for (const pose of this.info.poses) for (const track of this.clips.get(pose.name)!.tracks) left.add(track.node);
    this.leftBones = [...left];
    const surfaces = new Map<string, THREE.MeshStandardMaterial>();
    this.root.traverse(object => {
      if (!(object instanceof THREE.Mesh)) return;
      object.castShadow = true;
      object.receiveShadow = true;
      if (object instanceof THREE.SkinnedMesh) object.frustumCulled = false;
      for (const material of Array.isArray(object.material) ? object.material : [object.material]) {
        if (!(material instanceof THREE.MeshStandardMaterial)) continue;
        surfaces.set(material.name, material);
        if (material.name === 'APK_skin' || material.name === 'APK_wrist') {
          this.skin.add(material);
          material.onBeforeCompile = shader => {
            shader.fragmentShader = shader.fragmentShader.replace('#include <lights_fragment_end>',
              '#include <lights_fragment_end>\nreflectedLight.indirectDiffuse *= 0.5;');
          };
          material.customProgramCacheKey = () => 'apk-original-skin-v1';
          if (material.name === 'APK_wrist') { material.depthWrite = false; object.castShadow = false; }
        }
      }
    });
    const imageSize = (texture: THREE.Texture | null | undefined, size: number) => {
      const image: unknown = texture?.image;
      return image !== null && typeof image === 'object' && 'width' in image && 'height' in image && image.width === size && image.height === size;
    };
    for (const [name, size] of [['APK_acoustic', 1024], ['APK_rosette', 256], ['APK_skin', 1024], ['APK_wrist', 1024]] as const) {
      const material = surfaces.get(name);
      if (!imageSize(material?.map, size) || ((name === 'APK_skin' || name === 'APK_wrist') && !imageSize(material?.normalMap, 1024))) {
        throw new Error(`Original ${name.replace('APK_', '')} textures could not be decoded`);
      }
    }
    this.strings = Array.from({ length: 6 }, (_, s) => {
      const materials: THREE.MeshStandardMaterial[] = [];
      required(`APK_string_${s}`).traverse(object => {
        if (!(object instanceof THREE.Mesh)) return;
        for (const material of Array.isArray(object.material) ? object.material : [object.material]) {
          if (material instanceof THREE.MeshStandardMaterial) materials.push(material);
        }
      });
      return { materials, lastHit: -Infinity };
    });
    // Adapt from an authored wrist frame rather than a generic hand orientation.
    const sourceBases = ['F', 'G', 'Dm7'].map(name => {
      this.apply(name, Infinity);
      return required('LeftHand').getWorldQuaternion(new THREE.Quaternion());
    });
    this.apply('C', Infinity);
    this.fretting = new AuthoredHandRig(this.root, this.info, 'Left', prepared, sourceBases);
    this.picking = new AuthoredHandRig(this.root, this.info, 'Right');
    for (const [clip, finger] of [['i', 'index'], ['m', 'middle'], ['a', 'ring'], ['4_p', 'thumb'], ['5_p', 'thumb'], ['6_p', 'thumb']] as const) {
      this.apply('ArpDef', Infinity);
      this.apply(`${clip}_in`, Infinity);
      this.pluckContacts.set(clip, this.picking.point(finger));
    }
    this.apply('StrDef', Infinity);
    this.setHandsVisible(true);
  }

  private apply(name: string, time: number, weight = 1): void {
    const clip = this.clips.get(name);
    if (!clip) throw new Error(`Unknown original animation: ${name}`);
    for (const track of clip.tracks) {
      sampleAuthoredCurve(track, time, SAMPLE);
      if (track.property === 'quaternion') {
        ROTATION.fromArray(SAMPLE).normalize();
        if (weight === 1) track.node.quaternion.copy(ROTATION); else track.node.quaternion.slerp(ROTATION, weight);
      } else {
        POSITION.fromArray(SAMPLE);
        track.node[track.property].lerp(POSITION, weight);
      }
    }
  }

  private captureLeft(): BonePose[] {
    return this.leftBones.map(node => ({ position: node.position.clone(), quaternion: node.quaternion.clone() }));
  }

  private blendLeft(from: readonly BonePose[], to: readonly BonePose[], t: number): void {
    this.leftBones.forEach((node, i) => {
      node.position.lerpVectors(from[i].position, to[i].position, t);
      node.quaternion.slerpQuaternions(from[i].quaternion, to[i].quaternion, t).normalize();
    });
  }

  scheduleFrets(frets: Frets, at: number, stepSeconds: number, now: number): void {
    const key = shapeKey(frets);
    if (key === this.targetKey && !this.demo) return;
    this.demo = null;
    this.targetKey = key;
    const lead = THREE.MathUtils.clamp(.8 * stepSeconds, .1, .28), start = Math.max(now, at - lead);
    this.prepare(frets);
    this.chordQueue.push({ key, pose: { name: findAuthoredPose(this.info.poses, frets)?.name ?? 'Selected shape', frets: [...frets] }, start, end: Math.max(start + .06, at - .01) });
    this.chordQueue.sort((a, b) => a.start - b.start);
  }

  follow(frets: Frets, family: StageFamily, now: number): void {
    this.stop();
    this.demo = null;
    this.family = family;
    this.targetKey = shapeKey(frets);
    this.pose = { name: findAuthoredPose(this.info.poses, frets)?.name ?? 'Selected shape', frets: [...frets] };
    this.fretting.apply(this.fretting.solve(frets));
    this.update(now, true);
  }

  playStep(step: StageStep, at: number, reduced: boolean): void {
    this.demo = null;
    this.family = step.family;
    if (reduced) return;
    for (const note of step.notes) this.hits.push({ at: at + note.offset, string: note.stringIndex });
    if (step.family === 'pick') {
      for (const note of authoredPlucks(step.notes)) this.plucks.push({ ...note, at: at + note.offset });
    } else {
      const up = step.stroke === 'up' || (step.stroke === 'rest' && step.stepInBar % 2 === 1);
      const contactName = up ? 'Ycal' : 'Acal';
      const clip = step.notes.length ? contactName : up ? 'YuKu' : 'AsaKu';
      this.strokes.push({
        clip, keys: authoredStrokeKeys(this.info.strumContacts[contactName], this.clips.get(clip)!.duration, step, at),
      });
      this.strokes.sort((a, b) => a.keys[0].at - b.keys[0].at);
    }
  }

  setFamily(family: StageFamily): void { this.family = family; }
  prepare(frets: Frets): void { this.fretting.solve(frets); }

  stop(): void {
    this.strokes = [];
    this.plucks = [];
    this.hits = [];
    this.chordQueue = [];
    this.chordChange = null;
    for (const string of this.strings) string.lastHit = -Infinity;
  }

  previewClip(name: string, now: number): void {
    if (!this.clips.has(name)) throw new Error('Choose an original animation from the list');
    this.stop();
    const chord = this.info.poses.find(pose => pose.name === name);
    if (chord) this.pose = chord;
    this.demo = { clip: name, start: now, chord: Boolean(chord) };
    this.family = name === 'ArpDef' || /^[iam]_/.test(name) || /^[456]_p/.test(name) ? 'pick' : 'strum';
  }

  get preview(): string | null { return this.demo?.clip ?? null; }
  get frettingFrets(): Frets | null { return this.pose?.frets ?? null; }
  get hasFrettingPose(): boolean { return this.pose !== null; }
  get hasPickingMotion(): boolean { return true; }

  setHandsVisible(visible: boolean): void {
    this.handsVisible = visible;
    this.left.visible = visible && this.hasFrettingPose;
    this.right.visible = visible && this.hasPickingMotion;
    this.pick.visible = visible && this.family === 'strum';
  }

  setSkin(tone: SkinTone): void {
    const color = new THREE.Color(SKIN_TONES[tone].color), base = new THREE.Color(SKIN_TONES.light.color);
    color.setRGB(color.r / base.r, color.g / base.g, color.b / base.b);
    for (const material of this.skin) material.color.copy(color);
  }

  stringPoint(string: number, x: number): THREE.Vector3 {
    return authoredStringPoint(this.info, string, x);
  }

  update(now: number, reduced: boolean): boolean {
    let active = false;
    while (this.chordQueue.length && this.chordQueue[0].start <= now) {
      const change = this.chordQueue.shift()!;
      const from = this.captureLeft();
      this.pose = change.pose;
      this.fretting.apply(this.fretting.solve(this.pose.frets));
      this.chordChange = { from, to: this.captureLeft(), start: change.start, end: change.end };
    }
    if (this.chordChange) {
      const { from, to, start, end } = this.chordChange;
      const t = reduced ? 1 : smooth((now - start) / (end - start));
      this.blendLeft(from, to, t);
      if (t > 0 && t < 1) this.fretting.lift(Math.sin(Math.PI * t) * .14);
      if (t >= 1) this.chordChange = null; else active = true;
    }
    this.apply(this.family === 'pick' ? 'ArpDef' : 'StrDef', Infinity);
    if (this.demo) {
      const clip = this.clips.get(this.demo.clip)!;
      const time = reduced ? clip.duration : Math.min(clip.duration, Math.max(0, now - this.demo.start));
      this.apply(clip.name, time);
      active = time < clip.duration;
    } else if (!reduced) {
      if (this.family === 'pick') active = this.animatePicking(now) || active;
      else {
        this.strokes = this.strokes.filter(stroke => stroke.keys[stroke.keys.length - 1].at + .3 > now);
        let stroke: Stroke | undefined;
        for (const candidate of this.strokes) if (candidate.keys[0].at <= now) stroke = candidate;
        if (stroke) {
          const end = stroke.keys[stroke.keys.length - 1].at;
          this.apply(stroke.clip, authoredTime(stroke.keys, now), 1 - smooth((now - end - .1) / .2));
        }
        active = this.strokes.length > 0 || active;
      }
    } else { this.strokes = []; this.plucks = []; this.hits = []; }
    for (const hit of this.hits) if (hit.at <= now) this.strings[hit.string].lastHit = hit.at;
    this.hits = this.hits.filter(hit => hit.at > now);
    for (const string of this.strings) {
      const age = now - string.lastHit;
      const glow = !reduced && age >= 0 && age < 1.6 ? Math.exp(-age / .35) : 0;
      for (const material of string.materials) material.emissive.setRGB(.6 * glow, .49 * glow, .32 * glow);
      active = glow > 0 || active;
    }
    this.setHandsVisible(this.handsVisible);
    return active || this.chordQueue.length > 0 || this.hits.length > 0;
  }

  private animatePicking(now: number): boolean {
    this.plucks = this.plucks.filter(event => event.at + .12 > now);
    const events = new Map<ChainName, FingerPluck>();
    for (const event of this.plucks) {
      if (event.at - .06 > now) continue;
      const previous = events.get(event.finger);
      if (!previous || previous.at < event.at) events.set(event.finger, event);
    }
    const thumb = events.get('thumb');
    if (thumb) this.thumb = thumb.string;
    this.apply(`${authoredPickingFinger(this.thumb)}_t_out`, Infinity);
    for (const event of events.values()) {
      const name = event.clip;
      const before = now < event.at, clip = `${name}_${before ? 'in' : 'out'}`;
      const t = before ? (now - event.at + .06) / .06 : (now - event.at) / .12;
      this.apply(clip, THREE.MathUtils.clamp(t, 0, 1) * this.clips.get(clip)!.duration);
      const reference = this.pluckContacts.get(name)!;
      const target = this.picking.point(event.finger).add(this.stringPoint(event.string, reference.x).sub(reference));
      this.picking.retarget(event.finger, target);
    }
    return this.plucks.length > 0;
  }

  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    this.stop();
    disposeScene(this.root);
  }
}
